try:
    print('>>> x = (1, 2)')
    print('>>> y = 1j')
    print('>>> x %= y')
    print('>>> x')
    x = (1, 2)
    y = 1j
    x %= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
